package com.astra.tvhome;

import org.json.*;
import java.util.*;

/** Presentation settings only: importing a theme never executes commands or changes Android settings. */
final class LauncherPrefs {
    static LinkedHashSet<String> hidden(MainActivity a){LinkedHashSet<String> out=new LinkedHashSet<>();for(String p:a.pref().getString("hiddenApps","").split(","))if(!p.isEmpty())out.add(p);return out;}
    static List<Integer> order(MainActivity a,boolean includeHidden){LinkedHashSet<Integer> out=new LinkedHashSet<>();Set<String> hidden=includeHidden?Collections.emptySet():hidden(a);for(String pkg:a.pref().getString("appOrder","").split(","))for(int i=0;i<a.apps.size();i++)if(a.apps.get(i).pkg.equals(pkg)&&!hidden.contains(pkg))out.add(i);for(int i=0;i<a.apps.size();i++)if(a.apps.get(i).moduleCard&&!hidden.contains(a.apps.get(i).pkg))out.add(i);for(int i=0;i<a.apps.size();i++)if(!hidden.contains(a.apps.get(i).pkg))out.add(i);return new ArrayList<>(out);}
    static void show(MainActivity a,String pkg,boolean shown){Set<String> hidden=hidden(a);if(shown)hidden.remove(pkg);else hidden.add(pkg);a.pref().edit().putString("hiddenApps",String.join(",",hidden)).apply();a.applyLibraryPreferences();}
    static int move(MainActivity a,int id,int delta){List<Integer> order=order(a,true);int position=order.indexOf(id),target=Math.max(0,Math.min(order.size()-1,position+delta));Collections.swap(order,position,target);ArrayList<String> packages=new ArrayList<>();for(int index:order)packages.add(a.apps.get(index).pkg);a.pref().edit().putString("appOrder",String.join(",",packages)).apply();return target+1;}
    static JSONObject export(MainActivity a)throws Exception{JSONObject json=new JSONObject().put("schema",1).put("format","astra-launcher-settings");JSONObject values=new JSONObject();String[] keys={"motion","glow","detail","colorCycle","cameraPreview","sensitivity","handQuality","spaceSound","spaceSoundLevel","weatherEnabled","weatherCity","weatherLat","weatherLon","favorites","hiddenApps","appOrder","gridColumns","dockSlots","reducedMotion","showStats","showDate","idleClockMinutes","moduleCards","liveTvPackage","openOnStart"};Map<String,?> all=a.pref().getAll();for(String key:keys)if(all.containsKey(key))values.put(key,all.get(key));for(String key:all.keySet())if(key.matches("remote\\.\\d+\\.(tap|hold)"))values.put(key,all.get(key));json.put("values",values);return json;}
    static int importSettings(MainActivity a,String text)throws Exception{JSONObject document=new JSONObject(text),values=document.optJSONObject("values");if(values==null)values=document;android.content.SharedPreferences.Editor edit=a.pref().edit();int applied=0;
        String[][] booleans={{"motion","animations"},{"detail","detail"},{"colorCycle","colorCycle"},{"cameraPreview","cameraPreview"},{"spaceSound","spaceSound"},{"weatherEnabled","weatherEnabled"},{"reducedMotion","reduced_motion"},{"showStats","show_stats"},{"showDate","showDate"},{"moduleCards","module_cards"}};
        for(String[] pair:booleans){String key=values.has(pair[0])?pair[0]:pair[1];if(values.has(key)&&values.get(key) instanceof Boolean){edit.putBoolean(pair[0],values.getBoolean(key));applied++;}}
        String[] numeric={"glow","handQuality","spaceSoundLevel","gridColumns","dockSlots","idleClockMinutes"};int[] min={0,0,0,4,4,0},max={2,1,2,7,7,60};for(int i=0;i<numeric.length;i++){String key=numeric[i];String source=values.has(key)?key:key.equals("gridColumns")?"columns":key.equals("idleClockMinutes")?"home_idle_clock_minutes":key;if(values.has(source)){edit.putInt(key,Math.max(min[i],Math.min(max[i],values.getInt(source))));applied++;}}
        for(String[] pair:new String[][]{{"favorites","dock_apps"},{"hiddenApps","hidden_apps"},{"appOrder","app_order"}}){String key=values.has(pair[0])?pair[0]:pair[1];if(!values.has(key))continue;Object value=values.get(key);String csv=value instanceof JSONArray?join((JSONArray)value):String.valueOf(value);LinkedHashSet<String> found=new LinkedHashSet<>();for(String pkg:csv.split(",")){if(pkg.isEmpty())continue;Maintenance.packageName(pkg);for(NativeApp app:a.apps)if(app.pkg.equals(pkg))found.add(pkg);}edit.putString(pair[0],String.join(",",found));applied++;}
        if(values.has("sensitivity")){float sensitivity=(float)values.getDouble("sensitivity");if(!Float.isFinite(sensitivity))throw new IllegalArgumentException("无效灵敏度");edit.putFloat("sensitivity",Math.max(.5f,Math.min(1.5f,sensitivity)));applied++;}
        for(java.util.Iterator<String> keys=values.keys();keys.hasNext();){String key=keys.next();if(key.matches("remote\\.(183|184|185|186)\\.(tap|hold)")){String action=values.getString(key);if(action.matches("none|home|apps|inputs|settings|mute|app:[A-Za-z_][A-Za-z0-9_]*(\\.[A-Za-z0-9_]+)+")){edit.putString(key,action);applied++;}}
        }
        for(String key:new String[]{"liveTvPackage","openOnStart"})if(values.has(key)){String pkg=values.getString(key);if(!pkg.isEmpty()){Maintenance.packageName(pkg);boolean present=false;for(NativeApp app:a.apps)if(app.pkg.equals(pkg))present=true;if(!present)throw new IllegalArgumentException("所选应用未安装");}edit.putString(key,pkg);if(key.equals("openOnStart"))edit.putInt("lastAutoBoot",android.provider.Settings.Global.getInt(a.getContentResolver(),"boot_count",-1));applied++;}
        if(values.has("weatherCity")&&values.has("weatherLat")&&values.has("weatherLon")){String city=values.getString("weatherCity");double lat=values.getDouble("weatherLat"),lon=values.getDouble("weatherLon");if(city.length()>64||city.trim().isEmpty()||!Double.isFinite(lat)||!Double.isFinite(lon)||lat< -90||lat>90||lon< -180||lon>180)throw new IllegalArgumentException("无效天气位置");edit.putString("weatherCity",city).putFloat("weatherLat",(float)lat).putFloat("weatherLon",(float)lon).remove("weatherCache").remove("weatherAt");applied+=3;}
        edit.apply();return applied;
    }
    static String join(JSONArray values)throws JSONException{ArrayList<String> list=new ArrayList<>();for(int i=0;i<values.length();i++)list.add(values.getString(i));return String.join(",",list);}
}
